from fastapi import FastAPI, Depends, HTTPException, Header
from pydantic import BaseModel, EmailStr, Field, field_validator

app = FastAPI()

class UserCreate(BaseModel):
    email: EmailStr
    password: str = Field(min_length=8)
    name: str

    @field_validator("name")
    @classmethod
    def clean_name(cls, v: str) -> str:
        return v.strip().title()

class UserOut(BaseModel):
    id: int
    email: EmailStr
    name: str

class Pagination:
    def __init__(self, page: int = 1, size: int = 20):
        self.page, self.size = max(page, 1), min(size, 100)

def get_current_user(x_token: str = Header()):
    if x_token != "secret-token":
        raise HTTPException(status_code=401, detail="Invalid token")
    return {"id": 1, "email": "asha@example.com", "name": "Asha"}

@app.post("/users", response_model=UserOut, status_code=201)
def create_user(data: UserCreate):
    return {"id": 2, "email": data.email, "name": data.name}

@app.get("/me", response_model=UserOut)
def me(user: dict = Depends(get_current_user)):
    return user

@app.get("/users")
def list_users(p: Pagination = Depends(), user: dict = Depends(get_current_user)):
    return {"page": p.page, "size": p.size}

